import json, tempfile, shutil, subprocess, sys, hashlib
from pathlib import Path
source=Path.cwd()
root=Path(tempfile.mkdtemp(prefix="t9-independent-"))
records=[]
ref={"path":".allforai/bootstrap/local-requirements.json","id":"invoice-download","revision":1}
req={"id":"invoice-download","revision":1,"scope":["invoices"],"goal":"Download my invoices","business_rules":["Only owner invoices are accessible"],"acceptance":["Different owner request denied"],"status":"confirmed","confirmation":{"source":"user","reference":"synthetic user turn 1","decision_id":"invoice-approved","reason":"Keep customer invoices private"}}
node={"node_id":"invoice","goal":"Deliver private invoice download","capability":"implement","exit_artifacts":[".allforai/bootstrap/invoice-report.json"],"requirement_refs":[ref],"responsibilities":["implementation","documentation","verification"],"decision_inputs":[ref["path"]]}
profile={"task_goal":"Add invoice download","task_route":"local-change","task_scope":{"areas":["invoices"],"requirement_refs":[ref]}}
specbody="""## Attention Contract
- Primary outcome: private invoice download.
- Non-goals / out-of-scope: warehouse changes.
- Must-read inputs: local requirements invoice-download revision 1.
- Optional inputs: none.
- Context budget: invoice source only.
- Quality questions: are other owners denied?
- Stop conditions: pending decisions.
- Repair targets: invoice implementation.
"""
policy={"version":1,"run_mode":"unattended","forbid_mid_run_user_prompts":True,"forbid_hidden_fallback_completion":True,"max_repair_attempts":3,"required_capabilities":[],"required_repair_loops":[],"long_task_policy":dict.fromkeys(["file_based_handoff","polling","timeout","retry","resume"],True)}
def write(p,obj):
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj))
for host in ["claude","codex"]:
 p=root/host;b=p/".allforai/bootstrap";s=b/"scripts";s.mkdir(parents=True)
 for name in ["product_intent.py","validate_bootstrap.py","validate_unattended_readiness.py","check_artifacts.py"]:
  shutil.copy2(source/host/"meta-skill/scripts/orchestrator"/name,s/name)
 shutil.copy2(source/host/"meta-skill/scripts/check_decision_inputs.py",s/"check_decision_inputs.py")
 (p/"invoices.py").write_text("def invoices(owner): return []\n")
 write(b/"bootstrap-profile.json",profile);write(b/"local-requirements.json",{"requirements":[req]});write(b/"unattended-run-readiness-spec.json",policy)
 def publish(w):
  write(b/"workflow.json",w)
  for n in w.get("nodes",[]) or []:
   if isinstance(n,dict):
    path=b/"node-specs"/(n["node_id"]+".md");path.parent.mkdir(exist_ok=True);path.write_text("---\n"+json.dumps(n)+"\n---\n"+specbody)
 def gates(case):
  for name in ["validate_bootstrap.py","check_decision_inputs.py","validate_unattended_readiness.py"]:
   cmd=[sys.executable,str(s/name),str(b if name=="validate_bootstrap.py" else p)]
   if name=="validate_unattended_readiness.py":cmd+=["--write-report"]
   before={str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in [p/"invoices.py",b/"local-requirements.json"]}
   r=subprocess.run(cmd,cwd=p,text=True,capture_output=True)
   rec={"host_asset_path":str(source/host/"meta-skill/scripts"),"case":case,"command":cmd,"exit":r.returncode,"stdout":r.stdout,"stderr":r.stderr,"protected_unchanged":all(hashlib.sha256(Path(x).read_bytes()).hexdigest()==v for x,v in before.items())}
   report=b/"unattended-run-readiness.json"
   if name=="validate_unattended_readiness.py" and report.exists():rec["persisted_report"]=json.loads(report.read_text())
   records.append(rec)
 publish({"nodes":[node],"transition_log":[]});gates("valid-local")
 incomplete=json.loads(json.dumps(req));del incomplete["confirmation"]["reason"]
 write(b/"local-requirements.json",{"requirements":[incomplete]});gates("incomplete-confirmation")
 write(b/"local-requirements.json",{"requirements":[req]});gates("confirmation-reentry")
 for malformed in [{"nodes":None},{"nodes":[None]},{"nodes":["bad"]}]:
  write(b/"workflow.json",malformed);gates("malformed-"+json.dumps(malformed))
  publish({"nodes":[node],"transition_log":[]});gates("malformed-corrected-reentry")
 for refs in ["absent","empty"]:
  extra={"node_id":"warehouse","goal":"Change warehouse inventory","capability":"implement","exit_artifacts":[".allforai/bootstrap/stock.json"]}
  if refs=="empty":extra["requirement_refs"]=[]
  publish({"nodes":[node,extra],"transition_log":[]});gates("new-unscoped-"+refs)
  write(b/"stock.json",{"status":"passed","observations":["existing warehouse counts verified"]})
  publish({"nodes":[node,extra],"transition_log":[{"node_id":"warehouse","status":"completed"}]});gates("retained-completed-"+refs)
 publish({"nodes":[node],"transition_log":[]})
 for route in ["product-reconstruction","new-product"]:
  pr=json.loads(json.dumps(profile));pr["task_route"]=route;pr["task_scope"]={"areas":["product"],"requirement_refs":[]};write(b/"bootstrap-profile.json",pr);gates(route+"-unconfirmed")
 write(b/"bootstrap-profile.json",profile)
print(json.dumps({"fixture_root":str(root),"records":records}))

